// Deterministic asset export only; artwork is generated by built-in image_gen.
// Requires sharp in Node's module search path; not a game/build dependency.
import { createRequire } from "node:module";
import { readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
const sharp = createRequire(import.meta.url)("sharp");
const root = new URL("../../../", import.meta.url);
const report = [];
for (const id of ["warehouse_pickup", "warehouse_intake"]) {
  const source = new URL(`${id}-source.png`, import.meta.url);
  const { data } = await sharp(fileURLToPath(source))
    .resize(64, 64, {
      fit: "contain",
      background: { r: 0, g: 0, b: 0, alpha: 0 },
      kernel: "nearest",
    })
    .ensureAlpha()
    .raw()
    .toBuffer({ resolveWithObject: true });
  for (let i = 0; i < data.length; i += 4) {
    data[i + 3] = data[i + 3] >= 128 ? 255 : 0;
    if (!data[i + 3]) data.fill(0, i, i + 3);
  }
  const palette = await sharp(data, {
    raw: { width: 64, height: 64, channels: 4 },
  })
    .png({ palette: true, colours: 16, dither: 0 })
    .toBuffer();
  const raw = await sharp(palette).ensureAlpha().raw().toBuffer();
  const png = await sharp(raw, { raw: { width: 64, height: 64, channels: 4 } })
    .resize(128, 128, { kernel: "nearest" })
    .png({ palette: false })
    .toBuffer();
  await writeFile(
    new URL(`apps/web/src/assets/buildings/v1/${id}.png`, root),
    png,
  );
  const colors = new Set();
  for (let i = 0; i < raw.length; i += 4)
    if (raw[i + 3]) colors.add(raw.subarray(i, i + 3).toString("hex"));
  report.push({
    id,
    width: 128,
    height: 128,
    logical_size: 64,
    opaque_colors: colors.size,
    bytes: png.length,
    sha256: createHash("sha256").update(png).digest("hex"),
  });
}
const path = new URL("apps/web/src/assets/buildings/v1/manifest.json", root);
const manifest = JSON.parse(await readFile(path, "utf8"));
const catalog = JSON.parse(
  await readFile(
    new URL("apps/server/internal/catalog/definitions.json", root),
    "utf8",
  ),
);
for (const { id } of report) {
  const b = catalog.buildings.find((b) => b.id === id);
  manifest.buildings[id] = { renderer: "image", tier: b.tier, color: b.color };
}
await writeFile(path, JSON.stringify(manifest, null, 2) + "\n");
await writeFile(
  new URL("sprite-validation.json", import.meta.url),
  JSON.stringify(report, null, 2) + "\n",
);
console.log(JSON.stringify(report));
